/**
 * Sheets Page - Shows spreadsheet files (XLS, XLSX, CSV, etc.)
 */

import React from 'react';
import { useFiles } from '../../hooks/useFiles';
import { filesService } from '../../services';
import FileItem from '../../components/FileItem/FileItem';

const Sheets = () => {
  const { files, loading: filesLoading, downloadFile, refetch: refetchFiles } = useFiles(null);

  // Filter for spreadsheet files
  const spreadsheetTypes = [
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.oasis.opendocument.spreadsheet',
    'text/csv',
  ];

  const spreadsheetFiles = files.filter(file => {
    const mimeType = file.mime_type || file.mimeType || '';
    return spreadsheetTypes.some(type => mimeType.includes(type)) || 
           file.name?.toLowerCase().match(/\.(xls|xlsx|csv|ods)$/);
  });

  const handleDownload = async (fileId) => {
    try {
      await downloadFile(fileId);
    } catch (error) {
      alert(`Failed to download: ${error.message}`);
    }
  };

  const handleDelete = async (fileId) => {
    if (window.confirm('Move this file to trash?')) {
      try {
        await filesService.deleteFile(fileId);
        refetchFiles();
      } catch (error) {
        alert(`Failed to delete: ${error.message}`);
      }
    }
  };

  if (filesLoading) {
    return (
      <div className="sheets-page">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Loading spreadsheets...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="sheets-page">
      {spreadsheetFiles.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-content">
            <div className="empty-illustration">
              <svg width="180" height="180" viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg">
                <defs>
                  <linearGradient id="sheetsGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" style={{stopColor: '#34A853', stopOpacity: 1}} />
                    <stop offset="100%" style={{stopColor: '#0F9D58', stopOpacity: 1}} />
                  </linearGradient>
                </defs>
                <rect x="50" y="50" width="100" height="100" rx="4" fill="url(#sheetsGradient)" opacity="0.9"/>
                <line x1="70" y1="70" x2="130" y2="70" stroke="rgba(255,255,255,0.4)" strokeWidth="2"/>
                <line x1="70" y1="90" x2="130" y2="90" stroke="rgba(255,255,255,0.4)" strokeWidth="2"/>
                <line x1="70" y1="110" x2="130" y2="110" stroke="rgba(255,255,255,0.4)" strokeWidth="2"/>
                <line x1="70" y1="130" x2="130" y2="130" stroke="rgba(255,255,255,0.4)" strokeWidth="2"/>
                <line x1="70" y1="50" x2="70" y2="150" stroke="rgba(255,255,255,0.4)" strokeWidth="2"/>
                <line x1="100" y1="50" x2="100" y2="150" stroke="rgba(255,255,255,0.4)" strokeWidth="2"/>
                <line x1="130" y1="50" x2="130" y2="150" stroke="rgba(255,255,255,0.4)" strokeWidth="2"/>
              </svg>
            </div>
            <p className="empty-hint">No spreadsheets found. Upload XLS, XLSX, or CSV files to see them here.</p>
          </div>
        </div>
      ) : (
        <div className="file-grid">
          <div className="file-grid-header">
            <div className="file-header-name">Name</div>
            <div className="file-header-meta">Size</div>
            <div className="file-header-actions"></div>
          </div>
          {spreadsheetFiles.map((file) => (
            <FileItem
              key={file.id}
              file={file}
              onDownload={handleDownload}
              onDelete={handleDelete}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default Sheets;
